fn curated() -> &'static HashMap<&'static str, &'static str> {
    static CURATED: OnceLock<HashMap<&'static str, &'static str>> = OnceLock::new();
    CURATED.get_or_init(|| NAMES.iter().copied().collect())
}

/// Words for an emoji token (variation selectors and skin tones already
/// stripped). ZWJ sequences fall back to their first emoji (🤷‍♂ -> 🤷).
pub(crate) fn names(emoji: &str) -> Option<&'static str> {
    let t = curated();
    t.get(emoji).copied().or_else(|| {
        let first = emoji.chars().next()?;
        let mut buf = [0u8; 4];
        t.get(&*first.encode_utf8(&mut buf)).copied()
    })
}

/// The names table: `#` lines, then `emoji<TAB>name<TAB>keywords` with `|`
/// between the keywords.
const NAMES_TSV: &str = include_str!("emoji_names.tsv");

/// How a name matched an emoji in [`by_name`], best first: whole words of
/// the emoji's name, of a keyword, the start of a word of the name, of a
/// keyword, a typo.
const EXACT_NAME: u8 = 0;
const EXACT: u8 = 1;
const PREFIX_NAME: u8 = 2;
const PREFIX: u8 = 3;
const TYPO: u8 = 4;

/// A name of fewer letters selects nothing by a typo.
const MIN_TYPO_LETTERS: usize = 4;

/// One emoji of the names table.
#[derive(Debug)]
pub struct Emoji {
    /// Fully qualified, as Unicode writes it (`☠️`): what to put in a query.
    pub glyph: &'static str,
    /// Its CLDR short name, in English (`skull and crossbones`).
    pub name: &'static str,
    /// [`key`] of the glyph.
    key: Box<str>,
    /// The normalised words of the name and of each keyword: a space
    /// between words, `|` between the name and the keywords.
    words: Box<str>,
    /// Its place in the curated vocabulary, `u16::MAX` when not there.
    common: u16,
}

impl Emoji {
    /// What the emojis of items are compared with ([`key`]).
    pub fn key(&self) -> &str {
        &self.key
    }
}

/// The names table, parsed on first use (a few milliseconds). Plain scans
/// over it are fast enough (a fraction of a millisecond) and keep the
/// code small: every client carries it.
fn table() -> &'static [Emoji] {
    static TABLE: OnceLock<Vec<Emoji>> = OnceLock::new();
    TABLE.get_or_init(|| {
        let mut emojis = Vec::new();
        for line in NAMES_TSV.lines().filter(|l| !l.is_empty() && !l.starts_with('#')) {
            let mut cols = line.split('\t');
            let (Some(glyph), Some(name)) = (cols.next(), cols.next()) else {
                continue;
            };
            let words: Vec<String> = std::iter::once(name)
                .chain(cols.next().unwrap_or("").split('|'))
                .map(phrase_words)
                .filter(|w| !w.is_empty())
                .collect();
            let key = key(glyph);
            let common = match curated().contains_key(key.as_str()) {
                true => NAMES.iter().position(|(e, _)| *e == key),
                false => None,
            };
            emojis.push(Emoji {
                glyph,
                name,
                common: common.and_then(|i| u16::try_from(i).ok()).unwrap_or(u16::MAX),
                key: key.into(),
                words: words.join("|").into(),
            });
        }
        emojis
    })
}

/// The normalised words of `text`, a space between them: lowercase,
/// accents and apostrophes (also U+2019) removed (`Côte d'Ivoire` ->
/// `cote divoire`),
/// split at anything but a letter or a digit (`T-Rex` -> `t rex`).
fn phrase_words(text: &str) -> String {
    let norm: String = normalize(text)
        .chars()
        .filter(|c| !matches!(c, '\'' | '\u{2019}' | '\u{02BC}' | '`'))
        .collect();
    norm.split(|c: char| !c.is_alphanumeric())
        .filter(|w| !w.is_empty())
        .collect::<Vec<_>>()
        .join(" ")
}

/// The key emojis are compared by: without variation selectors and skin
/// tones (`👍🏽` and `👍` have the same key, as have `☠️` and `☠`).
pub fn key(emoji: &str) -> String {
    emoji_base(emoji.trim())
}

/// [`key`] with the skin tones kept: two `e:` emojis with the same toned
/// key are the same filter (`e:☠️` is `e:☠`, but `e:👍🏽` is not `e:👍`).
pub fn toned_key(emoji: &str) -> String {
    emoji_key(emoji)
}

/// Whether an `e:` value is a name (`skull`, `thumbs_up`, `t-rex`) rather
/// than an emoji: letters only, with `_` or `-` between words.
pub fn is_name(value: &str) -> bool {
    let value = value.trim();
    value.chars().any(char::is_alphabetic)
        && value
            .chars()
            .all(|c| (c.is_alphabetic() && !is_pictographic(c)) || c == '_' || c == '-')
}

/// The emoji of the table with the [`key`] of `emoji`: the same emoji,
/// skin tones and variation selectors aside.
pub fn find(emoji: &str) -> Option<&'static Emoji> {
    let k = key(emoji);
    table().iter().find(|e| *e.key == *k)
}

/// The English short name of an emoji (`skull` for 💀, with a variation
/// selector or a skin tone too); `None` when the table lacks it.
pub fn short_name(emoji: &str) -> Option<&'static str> {
    find(emoji).map(|e| e.name)
}

/// The emojis a name selects ([`is_name`]; anything else selects none),
/// best first. Case and accents are ignored; `_` and `-` separate words.
///
/// - A name selects every emoji with a word, in its name or in a keyword,
///   that starts with it: `skull` selects 💀 (skull) and ☠️ (skull and
///   crossbones), also 🩻 (x-ray, keyword skull) and 👲 (person with
///   skullcap). Several words must follow each other in one of them, the
///   last may be cut short: `thumbs_u` selects 👍.
/// - When that selects none and the name has 4 letters or more, words a
///   typo away select instead (a letter wrong, added or left out, or two
///   swapped; one in all): `sklul` selects what `skull` does.
///
/// Order: whole words before the start of one, a word of the name before
/// one of a keyword; then the curated emojis (most used on stickers
/// first), then Unicode's order.
pub fn by_name(name: &str) -> Vec<&'static Emoji> {
    if !is_name(name) {
        return Vec::new();
    }
    let text = phrase_words(name);
    let want: Vec<&str> = text.split(' ').filter(|w| !w.is_empty()).collect();
    if want.is_empty() {
        return Vec::new();
    }
    let t = table();
    // (how, common, index) packed in one number to sort by.
    let rank = |how: u8, e: &Emoji, i: usize| (u64::from(how) << 48) | (u64::from(e.common) << 32) | i as u64;
    let mut found: Vec<u64> = t
        .iter()
        .enumerate()
        .filter_map(|(i, e)| matched(&e.words, &want).map(|how| rank(how, e, i)))
        .collect();
    let letters: usize = want.iter().map(|w| w.chars().count()).sum();
    if found.is_empty() && letters >= MIN_TYPO_LETTERS {
        let want: Vec<Vec<char>> = want.iter().map(|w| w.chars().collect()).collect();
        found = t
            .iter()
            .enumerate()
            .filter(|(_, e)| typo(&e.words, &want))
            .map(|(i, e)| rank(TYPO, e, i))
            .collect();
    }
    found.sort_unstable();
    found.into_iter().map(|r| &t[(r & 0xFFFF_FFFF) as usize]).collect()
}

/// How `want` are words in a row of one phrase of `words` (the first is
/// the name): [`EXACT_NAME`] and so on; the last may only start a word.
fn matched(words: &str, want: &[&str]) -> Option<u8> {
    let (last, init) = want.split_last()?;
    let mut best: Option<u8> = None;
    for (n, phrase) in words.split('|').enumerate() {
        let (exact, prefix) = if n == 0 {
            (EXACT_NAME, PREFIX_NAME)
        } else {
            (EXACT, PREFIX)
        };
        let kind = |end: &str| match end {
            _ if end == *last => Some(exact),
            _ if end.starts_with(last) => Some(prefix),
            _ => None,
        };
        let found = if init.is_empty() {
            phrase.split(' ').filter_map(kind).min()
        } else {
            let ws: Vec<&str> = phrase.split(' ').collect();
            ws.windows(want.len())
                .filter(|run| run[..init.len()] == *init)
                .filter_map(|run| kind(run[init.len()]))
                .min()
        };
        best = match (best, found) {
            (Some(a), Some(b)) => Some(a.min(b)),
            (a, b) => a.or(b),
        };
        if best == Some(EXACT_NAME) {
            break;
        }
    }
    best
}

/// Whether `want`, but for one typo in all, are words in a row of one
/// phrase of `words`.
fn typo(words: &str, want: &[Vec<char>]) -> bool {
    if let [one] = want {
        return words.split([' ', '|']).any(|w| {
            w.chars().count().abs_diff(one.len()) <= 1
                && osa_within(one, &w.chars().collect::<Vec<char>>(), 1).is_some()
        });
    }
    for phrase in words.split('|') {
        let ws: Vec<Vec<char>> = phrase.split(' ').map(|w| w.chars().collect()).collect();
        for run in ws.windows(want.len()) {
            let mut edits = 0;
            for (w, q) in run.iter().zip(want) {
                match osa_within(q, w, 1 - edits) {
                    Some(d) => edits += d,
                    None => {
                        edits = 2;
                        break;
                    }
                }
            }
            if edits <= 1 {
                return true;
            }
        }
    }
    false
}

#[cfg(test)]
mod tests {
    use super::*;

    /// The names table has every curated emoji with its words: after a
    /// change to `NAMES`, run `scripts/gen-emoji-data.py`.
    #[test]
    fn the_table_has_the_curated_words() {
        for (emoji, words) in NAMES {
            let e = find(emoji).unwrap_or_else(|| panic!("{emoji} is not in emoji_names.tsv"));
            for w in words.split(' ') {
                assert!(
                    by_name(w).iter().any(|f| std::ptr::eq(*f, e)),
                    "{w} does not select {emoji}: regenerate emoji_names.tsv"
                );
            }
        }
        assert!(table().len() > 1900);
    }
}
